mapper.select:
select distinct sr.Role_ID roleId,sr.Role_Name roleName from SYS_Position_P spp left join SYS_PositionP_Role spr on spp.PP_ID=spr.PP_ID left join SYS_Department_P sdp on sdp.PD_ID=spp.PD_ID left join SYS_Role sr on sr.Role_ID=spr.Role_ID left join SYS_Position_User_P spup on spup.PP_ID=spp.PP_ID
spr.Role_ID is not null
and sdp.P_ID=#{pId}
and spup.U_ID=#{uId}
